// SpotifyCallback.js
import React, { useEffect } from 'react';
import { exchangeToken } from '../services/api';

const SpotifyCallback = ({ setIsAuthorized }) => {
  useEffect(() => {
    const fetchToken = async () => {
      const urlParams = new URLSearchParams(window.location.search);
      const code = urlParams.get('code');
      console.log("Received authorization code:", code);

      try {
        const { access_token } = await exchangeToken(code);
        console.log("Access token received:", access_token);

        // Store the token and update authorization status
        localStorage.setItem('access_token', access_token);
        console.log("Access token stored in localStorage");

        setIsAuthorized(true);
        console.log("Authorization status updated to true");
      } catch (error) {
        console.error("Error exchanging code for token:", error);
        setIsAuthorized(false);
      }
    };

    fetchToken();
  }, [setIsAuthorized]);

  return <div>Processing Authorization...</div>;
};

export default SpotifyCallback;
